#!/usr/bin/env python3
"""A.C.E. 1.7.0 — complete command-center visual redesign.

Loads the released 1.6.5 runtime unchanged underneath a new dark-green / lime
interface based on the approved reference images. Keeps all 1.6.5 capabilities and
adds the visible Live dashboard interactions from the reference: current chat,
project and work state, recent conversation, active artifact progress, Preview,
Start Live / Voice controls, a typed Live input, and consolidated navigation/tools.
"""
from pathlib import Path
import base64, importlib.util, zlib

H=Path(__file__).resolve().parent
BASE=H/'ACE Base 1.6.5.py'
spec=importlib.util.spec_from_file_location('ace_base_165',str(BASE))
b165=importlib.util.module_from_spec(spec);spec.loader.exec_module(b165)
ace=b165.ace
ace.VERSION='1.7.0'
try: ace.UPDATE_STATE['current_version']='1.7.0'
except Exception: pass

def patch(path,marker,transform):
    try:
        p=Path(path);s=p.read_text(encoding='utf-8')
        if marker in s:return True
        n=transform(s)
        if n!=s:p.write_text(n,encoding='utf-8')
        return marker in n
    except Exception:return False

def idx170(s):
    s=s.replace('app.css?v=165-attachments','app.css?v=170-command-center')
    s=s.replace('app.js?v=165-attachments','app.js?v=170-command-center')
    s=s.replace('Current version: v1.6.5','Current version: v1.7.0')
    return s+'\n<!--ACE170_COMMAND_CENTER-->\n'

CSS170=zlib.decompress(base64.b64decode('')).decode('utf-8')
JS170=zlib.decompress(base64.b64decode('')).decode('utf-8')

patch(H/'index.html','ACE170_COMMAND_CENTER',idx170)
patch(H/'app.css','ACE170_COMMAND_CENTER',lambda s:s+'\n'+CSS170+'\n')
patch(H/'app.js','ACE170_COMMAND_CENTER',lambda s:s+'\n'+JS170+'\n// ACE170\n')

if __name__=='__main__': ace.main()
